SELECT percentile_cont(0.75) within GROUP (ORDER BY icustays.los) AS percentile_75 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND patients.anchor_age = 42 AND admissions.admission_type = 'H' AND icustays.intime <= '2018-06-01' AND icustays.outtime >= '2018-12-31' AND (icustays.los / (60 * 60 * 24))::FLOAT >= 1;